### 3️⃣ `app.js`

```js
/* ==== Configuration ==== */
const CLIENT_ID = "YOUR_DISCORD_CLIENT_ID";   // <-- replace
const REDIRECT_URI = `${window.location.origin}/`; // must be whitelisted in Discord dev portal
const SCOPES = "identify guilds";

/* ==== UI Helpers ==== */
const $ = (s) => document.querySelector(s);
const show = (el) => el.classList.remove('hidden');
const hide = (el) => el.classList.add('hidden');

/* ==== OAuth2 Flow ==== */
function getAuthUrl() {
  const params = new URLSearchParams({
    client_id: CLIENT_ID,
    redirect_uri: REDIRECT_URI,
    response_type: "token",
    scope: SCOPES,
  });
  return `https://discord.com/api/oauth2/authorize?${params}`;
}

/* Parse access token from URL fragment */
function parseToken() {
  const hash = window.location.hash.substring(1);
  const params = new URLSearchParams(hash);
  return params.get('access_token');
}

/* Store token in sessionStorage (simple, not production‑grade) */
function storeToken(tok) {
  sessionStorage.setItem('discord_token', tok);
}
function clearToken() {
  sessionStorage.removeItem('discord_token');
}

/* ==== Dashboard Rendering ==== */
async function loadDashboard(token) {
  try {
    // ---- 1️⃣ Fetch user (just to prove token works) ----
    const userRes = await fetch('https://discord.com/api/users/@me', {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!userRes.ok) throw new Error('Invalid token');

    const user = await userRes.json();
    document.title = `${user.username} • MyBot Dashboard`;

    // ---- 2️⃣ Fetch bot stats from your backend ----
    // Expect JSON: { status: "online", guilds: 42, commandsUsed: 1234, commands: [{name,desc,usage},...] }
    const statsRes = await fetch('/api/bot-stats', {
      headers: { Authorization: `Bearer ${token}` },
    });
    const stats = await statsRes.json();

    // Populate cards
    $('#botStatus').textContent = stats.status;
    $('#guildCount').textContent = stats.guilds;
    $('#cmdCount').textContent = stats.commandsUsed;

    // Populate command list
    const ul = $('#commandList');
    ul.innerHTML = ''; // clear
    stats.commands.forEach(c => {
      const li = document.createElement('li');
      li.innerHTML = `
        <span class="command-name">/${c.name}</span><br>
        <span class="command-desc">${c.desc}</span><br>
        <span class="command-usage">Usage: ${c.usage}</span>
      `;
      ul.appendChild(li);
    });

    // Show dashboard, hide login
    hide($('#loginBtn'));
    show($('#logoutBtn'));
    show($('#dashboard'));
  } catch (e) {
    console.error(e);
    alert('Failed to load dashboard – try logging in again.');
    clearToken();
    location.reload();
  }
}

/* ==== Event Listeners ==== */
$('#loginBtn').addEventListener('click', () => {
  window.location.href = getAuthUrl();
});

$('#logoutBtn').addEventListener('click', () => {
  clearToken();
  location.reload();
});

/* ==== Init ==== */
(function init() {
  const tokenFromUrl = parseToken();
  const stored = sessionStorage.getItem('discord_token');

  if (tokenFromUrl) {
    storeToken(tokenFromUrl);
    // Clean the URL (remove fragment)
    history.replaceState(null, null, window.location.pathname);
    loadDashboard(tokenFromUrl);
  } else if (stored) {
    loadDashboard(stored);
  } else {
    // No token – stay on login screen
    show($('#loginBtn'));
  }
})();
```

